import torch

def update_ema(ema_model, model, decay: float) -> None:
    with torch.no_grad():
        ema_params = dict(ema_model.named_parameters())
        model_params = dict(model.named_parameters())
        for name, param in ema_params.items():
            if name in model_params:
                param.mul_(decay).add_(model_params[name], alpha=1 - decay)

        ema_buffers = dict(ema_model.named_buffers())
        model_buffers = dict(model.named_buffers())
        for name, buffer in ema_buffers.items():
            if name in model_buffers:
                buffer.copy_(model_buffers[name])

import math

class EarlyStopping:
    def __init__(self, patience=5, min_delta=0.0):
        if patience < 1:
            raise ValueError("patience must be >= 1")
        if min_delta < 0:
            raise ValueError("min_delta must be >= 0")
        self.patience = patience
        self.min_delta = min_delta
        self.best = None
        self.bad_epochs = 0

    def step(self, metric):
        # Check if metric is finite
        if not math.isfinite(metric):
            self.bad_epochs += 1
            return self.bad_epochs >= self.patience

        # First finite metric establishes best
        if self.best is None:
            self.best = metric
            self.bad_epochs = 0
            return False

        # Check for improvement: metric < best - min_delta
        if metric < self.best - self.min_delta:
            self.best = metric
            self.bad_epochs = 0
            return False
        else:
            self.bad_epochs += 1
            return self.bad_epochs >= self.patience

def freeze_for_finetuning(model, trainable_prefixes):
    trainable_count = 0
    for name, param in model.named_parameters():
        if trainable_prefixes and any(name.startswith(prefix) for prefix in trainable_prefixes):
            param.requires_grad = True
            trainable_count += param.numel()
        else:
            param.requires_grad = False
    return trainable_count

import numpy as np

def update_centroid_tracks(prev_tracks, detections, max_distance: float) -> dict:
    # Convert detections to numpy array for easier handling
    if len(detections) == 0:
        detections = np.array([]).reshape(0, 2)
    else:
        detections = np.array(detections)
        if detections.ndim == 1:
            detections = detections.reshape(1, -1)

    # Initialize result with previous tracks that will be updated
    result = {}

    # Get previous track IDs and centroids
    prev_ids = list(prev_tracks.keys())
    prev_centroids = [prev_tracks[tid] for tid in prev_ids]

    # Build candidate pairs
    candidates = []
    for i, tid in enumerate(prev_ids):
        p_centroid = np.array(prev_centroids[i], dtype=np.float64)
        for j, det_centroid in enumerate(detections):
            det_centroid = np.array(det_centroid, dtype=np.float64)
            dist = np.linalg.norm(p_centroid - det_centroid)
            if dist <= max_distance:
                candidates.append((dist, tid, j))

    # Sort candidates by (distance, track_id, detection_index)
    candidates.sort(key=lambda x: (x[0], x[1], x[2]))

    # Greedy assignment
    matched_tracks = set()
    matched_detections = set()

    for dist, tid, det_idx in candidates:
        if tid not in matched_tracks and det_idx not in matched_detections:
            matched_tracks.add(tid)
            matched_detections.add(det_idx)
            result[tid] = np.array(detections[det_idx], dtype=np.float64)

    # Assign new IDs to unmatched detections
    if prev_ids:
        next_id = max(prev_ids) + 1
    else:
        next_id = 0

    for j, det_centroid in enumerate(detections):
        if j not in matched_detections:
            result[next_id] = np.array(det_centroid, dtype=np.float64)
            next_id += 1

    return result
